// Clockwork Dominion: an incremental game in three acts (docs/carts/clockwork-dominion.md).
// Pip, a clockwork automaton, makes cogs in Hollis Wren's shop, and winds up the town, the world and the stars.
//
// The code is the engine; the book (the font and the story) is in the ROM, made by book.py. The rules are one
// simulation, step(dt), run 10 times a second (every 6 frames) by the cart and as fast as it can go by the tests and the
// bot. Everything a run is, is in G (saved to the slots by saveRun, read back by loadRun).

// ART (generated by art.py: do not edit)
const ART = {
  tiles: {},
  sprites: {"cog": {"pal": 0, "size": 8, "tile": 258}, "pip": {"pal": 0, "size": 16, "tile": 256}, "tinker": {"pal": 0, "size": 8, "tile": 259}},
  scenes: {"bench": {"h": 3, "mx": 0, "my": 0, "pal": 1, "w": 32}},
  colors: {"BAD": 119, "BRASS": 117, "DIM": 116, "EDGE": 121, "GOLD": 118, "GOOD": 120, "INK": 115, "LINE": 122, "LOG": 124, "PAPER": 113, "ROW": 114, "THINK": 123},
  gradients: {"wall":{"entry":0,"lines":[2183,2183,2183,2216,2216,2216,3240,3241,3241,3241,3273,3274,3274,3274,3274,3275,3275,4331,4331,4332,4332,4332,4333,4365,4365,4365,4365,4365,4366,4366,5422,5422,5422,5423,5423,5423,5423,5455,5455,5456,5456,5456,5456,5456,5488,5489,6513,5489,5456,5456,5456,5455,5455,5423,5423,5422,5422,5422,4365,4365,4365,4365,4364,4332,4332,4332,4331,4331,4331,3275,3274,3274,3274,3273,3273,3241,3241,3240,3240,3240,3240,2183,2183,2183,2183,2182,2182,2150,2150,2149,2149,2149],"y0":0}},
};
/** In scanline(y): set the CGRAM entry of a gradient from ART.gradients to its colour for line y (generated by art.py). */
function gradientLine(g, y) {
  const v = g.lines[y - g.y0];
  if (v !== undefined) color(g.entry, v & 31, (v >> 5) & 31, v >> 10);
}
// END ART
/** Queue one of ART.sprites at (x, y), above the background; opts as for spr (fx, fy ...). */
function sprite(s, x, y, opts = {}) { spr(s.tile, x, y, { size: s.size, pal: s.pal, prio: 3, ...opts }); }

// --- Colours: the panel's ink (art.py: overlay colours 113 and up) ---
const CO = ART.colors;
const PAPER = CO.PAPER, ROWC = CO.ROW, INK = CO.INK, DIM = CO.DIM, BRASS = CO.BRASS, GOLD = CO.GOLD, BAD = CO.BAD;
const GOOD = CO.GOOD, EDGE = CO.EDGE, LINE = CO.LINE, THINK = CO.THINK, LOGC = CO.LOG;

// --- The screen (spec section 4) ---
const VIEW_H = 92, TAB_Y = 92, PANEL_Y = 104, LOG_Y = 194, ROWS_SHOWN = 5;
const LM = '\x7f', RM = '\x80', DOT = '\x81', COG = '\x82'; // the ledger font's extra characters

// --- Sound (SPEC 5): songs on channels 0 to 5, effects take turns on 6 and 7 ---
const SFX = { move: 0, select: 1, pause: 2, no: 3, over: 4, clink: 5, story: 6 };
const SONG = { title: 0, play: 1 };
const SFX_CH = [7, 6];
let fxNext = 0, soundOn = 1, musicOn = 1, playing = -1;
function fx(n) { if (!soundOn) return; sfx(n, SFX_CH[fxNext]); fxNext ^= 1; }
function play(song) {
  if (!musicOn) song = -1;
  if (song === playing) return;
  playing = song; music(song);
}

// --- The ledger font (rom/font.bin, from book.py): 5 x 7 letters, 9 rows with the descenders ---
let GW = null, GP = null; // each glyph's width, and its lit pixels as [dx, dy, dx, dy ...]
function loadFont() {
  const b = rom('font'), n = b.length / 10;
  GW = new Uint8Array(n); GP = [];
  for (let g = 0; g < n; g++) {
    GW[g] = b[g * 10];
    const px = [];
    for (let y = 0; y < 9; y++) for (let x = 0; x < 5; x++) if ((b[g * 10 + 1 + y] >> x) & 1) px.push(x, y);
    GP.push(px);
  }
}
const gi = (ch) => { const g = ch.charCodeAt(0) - 32; return g >= 0 && g < GW.length ? g : 31; };
/** The width of a string in the ledger font, in pixels. */
function tw(s) { let w = 0; for (const ch of s) w += GW[gi(ch)] + 1; return w ? w - 1 : 0; }
/** Draw a string in the ledger font; returns the x after it. */
function tx(s, x, y, c) {
  for (const ch of s) {
    const g = gi(ch), px = GP[g];
    for (let k = 0; k < px.length; k += 2) pset(x + px[k], y + px[k + 1], c);
    x += GW[g] + 1;
  }
  return x;
}
const txr = (s, x, y, c) => tx(s, x - tw(s), y, c);
const txc = (s, y, c) => tx(s, 128 - (tw(s) >> 1), y, c);
/** Break text into lines that fit in w pixels. */
function wrap(s, w) {
  const out = []; let line = '';
  for (const word of s.split(' ')) {
    const next = line ? line + ' ' + word : word;
    if (tw(next) > w && line) { out.push(line); line = word; } else line = next;
  }
  if (line) out.push(line);
  return out;
}
/** System-font text with a shadow. */
function sys(s, x, y, c) { print(s, x + 1, y + 1, EDGE); print(s, x, y, c); }
const sysc = (s, y, c) => sys(s, 128 - s.length * 4, y, c);

// --- Numbers (spec 5: by name to decillion, then 1.2E36) ---
const BIG = ['thousand', 'million', 'billion', 'trillion', 'quadrillion', 'quintillion', 'sextillion', 'septillion',
  'octillion', 'nonillion', 'decillion'];
function commas(n) { return Math.floor(n).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ','); }
function fmt(n) {
  if (!(n >= 1e6)) return commas(Math.max(0, n));
  const e = Math.floor(Math.log10(n) / 3);
  if (e <= BIG.length) return (n / 10 ** (3 * e)).toFixed(2) + ' ' + BIG[e - 1];
  return n.toExponential(1).toUpperCase().replace('+', '');
}
const SHORT = ['K', 'M', 'B', 'T', 'Qa', 'Qi', 'Sx', 'Sp', 'Oc', 'No', 'Dc'];
/** Short numbers for the panels' counters: 999,999 then 1.24M, 3.50B ... */
function fmts(n) {
  if (!(n >= 1e6)) return commas(Math.max(0, n));
  const e = Math.floor(Math.log10(n) / 3);
  if (e <= SHORT.length) return (n / 10 ** (3 * e)).toFixed(2) + SHORT[e - 1];
  return n.toExponential(1).toUpperCase().replace('+', '');
}
const money = (n) => (n < 1000 ? '$' + n.toFixed(2) : '$' + fmts(n));
const rate = (n) => (n < 10 ? n.toFixed(1) : fmts(n));

// --- The rules' numbers (spec section 5; the tests read them from here) ---
const T = {
  brass0: 1000, spoolOz: 1000, spool0: 15, spoolRise: 1.5, spoolFall: 0.03, mktLow: 12, mktHigh: 24, dayLen: 360,
  price0: 0.25, priceStep: 0.01, priceMin: 0.01, priceMax: 99.99,
  sales0: 3, signMul: 1.3, priceExp: 1.6, signCost: 100, signMax: 30,
  tinkerCost: 5, tinkerMul: 1.12, tinkerRate: 1,
  unsold: 150, // cogs in stock that make the town's indifference a story line
};
const TICK = 0.1, TICK_FRAMES = 6, SAVE_EVERY = 600;

// --- The run: everything in G is the game (saved by saveRun) ---
// The order of SAVE_KEYS is the save's layout: add new keys at the end, never reorder.
const SAVE_KEYS = ['made', 'cogs', 'brass', 'coin', 'price', 'sign', 'tinkers', 'spool', 'day', 'sold', 'spools',
  'time', 'mk', 'priceMoves'];
let G = null;
function freshRun(seed) {
  return {
    seed, act: 1, made: 0, cogs: 0, brass: T.brass0, coin: 0, price: T.price0, sign: 1, tinkers: 0, spool: T.spool0,
    day: 0, sold: 0, spools: 0, time: 0, mk: 0, priceMoves: 0, told: new Uint32Array(16),
  };
}

const market = () => T.mktLow + (T.mktHigh - T.mktLow) * (0.5 - 0.5 * Math.cos((2 * Math.PI * G.day) / T.dayLen));
/** Cogs the town buys a second, at the current price and sign. */
const salesRate = () => T.sales0 * T.signMul ** (G.sign - 1) * (T.price0 / G.price) ** T.priceExp;
const tinkerCost = () => T.tinkerCost * T.tinkerMul ** G.tinkers;
const signCost = () => T.signCost * 2 ** (G.sign - 1);
const makeRate = () => G.tinkers * T.tinkerRate;

/** Make up to n cogs from the brass there is; returns how many. */
function make(n) {
  n = Math.min(n, Math.floor(G.brass));
  if (n <= 0) { raise('nobrass'); return 0; }
  G.brass -= n; G.cogs += n; G.made += n;
  return n;
}

/** One tick of the world: dt seconds. */
function step(dt) {
  G.time += dt; G.day += dt;
  G.spool += (market() - G.spool) * (1 - (1 - T.spoolFall) ** dt);
  G.mk += makeRate() * dt;
  if (G.mk >= 1) { const n = Math.floor(G.mk); G.mk -= n; make(n); }
  const s = Math.min(G.cogs, salesRate() * dt);
  G.cogs -= s; G.sold += s; G.coin += s * G.price;
  if (G.cogs >= T.unsold) raise('unsold');
  checkStory();
}

// --- What the player can do (the panel's rows and the hand call these; the bot and the tests too) ---
let why = ''; // why the last action could not be done, for the hint line
const no = (s) => { why = s; return false; };
const ACT = {
  hand() { return make(1) ? true : no('No brass left. Buy a spool from the merchant.'); },
  price(d) {
    const p = Math.round((G.price + d * T.priceStep) * 100) / 100;
    if (p < T.priceMin || p > T.priceMax) return no('That is as far as the price goes.');
    G.price = p; G.priceMoves++; raise(d > 0 ? 'priceup' : 'pricedown');
    return true;
  },
  brass() {
    if (G.coin < G.spool) return no('Not enough coin for a spool.');
    G.coin -= G.spool; G.brass += T.spoolOz; G.spool += T.spoolRise; G.spools++;
    return true;
  },
  sign() {
    if (G.sign >= T.signMax) return no('The sign is as grand as it can be.');
    const c = signCost(); if (G.coin < c) return no('Not enough coin to repaint the sign.');
    G.coin -= c; G.sign++;
    return true;
  },
  tinker() {
    const c = tinkerCost(); if (G.coin < c) return no('Not enough coin for the parts.');
    G.coin -= c; G.tinkers++;
    return true;
  },
};

// --- The story (rom/book.bin, from story.txt): each line told once a run, when its trigger first holds ---
let STORY = []; // { k, n } for a number's trigger, { ev } for an event's; and the text
function loadBook() {
  const b = rom('book'); let i = 5;
  const str = () => { const n = b[i++]; let s = ''; for (let k = 0; k < n; k++) s += String.fromCharCode(b[i++]); return s; };
  const count = b[3] | (b[4] << 8);
  STORY = [];
  for (let j = 0; j < count; j++) {
    const trig = str(), text = str(), c = trig.indexOf(':');
    const e = { text };
    if (trig.startsWith('ev:')) e.ev = trig.slice(3); else { e.k = trig.slice(0, c); e.n = +trig.slice(c + 1); }
    STORY.push(e);
  }
}
const isTold = (j) => (G.told[j >> 5] >>> (j & 31)) & 1;
function tell(j) { G.told[j >> 5] |= 1 << (j & 31); addLog(STORY[j].text, true); }
function checkStory() {
  for (let j = 0; j < STORY.length; j++) { const e = STORY[j]; if (e.k && !isTold(j) && G[e.k] >= e.n) tell(j); }
}
function raise(ev) {
  for (let j = 0; j < STORY.length; j++) if (STORY[j].ev === ev && !isTold(j)) tell(j);
}

// --- The log: the story's lines, wrapped; the newest types itself in ---
const LOG_W = 246;
let logRows = [], typed = 0, typing = 0, logScroll = 0;
function addLog(text, fresh) {
  const rows = wrap(text, LOG_W);
  rows.forEach((s, k) => logRows.push({ s, first: k === 0 }));
  if (logRows.length > 400) logRows.splice(0, logRows.length - 400);
  if (fresh) { typing = rows.length; typed = 0; if (state === 'play') fx(SFX.story); }
}
/** Rebuild the log from the lines told (after loading a run), in the story's order. */
function rebuildLog() {
  logRows = []; typing = 0;
  for (let j = 0; j < STORY.length; j++) if (isTold(j)) addLog(STORY[j].text, false);
}

// --- Save slots (spec section 13). Doubles take two slots: their 64 bits as two int32 ---
const VERSION_SLOT = 0, SAVE_VERSION = 2, CYCLE_SLOT = 1, RUN_SLOT = 2, TIME_SLOT = 3, SEED_SLOT = 5, SET_SLOT = 6;
const UI_SLOT = 7, KEYS_SLOT = 10, TOLD_SLOT = 138;
const f64 = new Float64Array(1), i32 = new Int32Array(f64.buffer);
function putD(slot, v) { f64[0] = v; dset(slot, i32[0]); dset(slot + 1, i32[1]); }
function getD(slot) { i32[0] = dget(slot); i32[1] = dget(slot + 1); return f64[0]; }
function saveRun() {
  dset(RUN_SLOT, 1 | (G.act << 8)); putD(TIME_SLOT, G.time); dset(SEED_SLOT, G.seed);
  dset(UI_SLOT, tab | (row << 8));
  SAVE_KEYS.forEach((k, i) => putD(KEYS_SLOT + 2 * i, G[k]));
  for (let i = 0; i < 16; i++) dset(TOLD_SLOT + i, G.told[i] | 0);
}
const hasRun = () => (dget(RUN_SLOT) & 255) === 1;
function loadRun() {
  G = freshRun(dget(SEED_SLOT));
  G.act = (dget(RUN_SLOT) >> 8) & 255;
  SAVE_KEYS.forEach((k, i) => { G[k] = getD(KEYS_SLOT + 2 * i); });
  for (let i = 0; i < 16; i++) G.told[i] = dget(TOLD_SLOT + i) >>> 0;
  const ui = dget(UI_SLOT); tab = ui & 255; row = (ui >> 8) & 255;
  rebuildLog();
}
function saveSettings() { dset(SET_SLOT, (soundOn ? 1 : 0) | (musicOn ? 2 : 0) | 4); }
function loadSettings() { const s = dget(SET_SLOT); if (s & 4) { soundOn = s & 1; musicOn = (s >> 1) & 1; } }

// --- The panels (spec 4): each tab gives its counters and its rows ---
// A row: t, its label; v(), its value or cost; a(), what A does; ok(), whether it can be done now; adj(d), for ◄ ►;
// h(), the hint for it.
const TABS = [
  {
    name: 'WORKSHOP',
    info: () => [`In stock ${fmts(G.cogs)}`, `Brass ${fmts(G.brass)} oz`, `Town buys ${rate(salesRate())}/s`],
    rows: () => [
      { t: 'Make a cog', v: () => 'B', a: ACT.hand, ok: () => G.brass >= 1, h: () => 'One cog from 1 oz of brass. B makes one from any panel.' },
      { t: 'Price per cog', v: () => `${LM} ${money(G.price)} ${RM}`, adj: (d) => ACT.price(d), ok: () => true, h: () => 'LEFT and RIGHT. Dearer sells fewer, but earns more.' },
      { t: `Buy brass, ${fmt(T.spoolOz)} oz`, v: () => money(G.spool), a: ACT.brass, ok: () => G.coin >= G.spool, h: () => `The price follows the market day: near ${money(market())} now.` },
      { t: `Shop sign, level ${G.sign}`, v: () => (G.sign >= T.signMax ? 'done' : money(signCost())), a: ACT.sign, ok: () => G.sign < T.signMax && G.coin >= signCost(), h: () => `A grander sign: the town buys ${Math.round((T.signMul - 1) * 100)}% more.` },
    ],
  },
  {
    name: 'HELPERS', when: () => G.made >= 20 || G.tinkers > 0,
    info: () => [`Tinkers ${fmts(G.tinkers)}`, `making ${rate(makeRate())}/s`],
    rows: () => [
      { t: 'Wind up a tinker', v: () => money(tinkerCost()), a: ACT.tinker, ok: () => G.coin >= tinkerCost(), h: () => `Each tinker makes ${T.tinkerRate} cog a second from the brass.` },
    ],
  },
];
let tab = 0, row = 0, top = 0, hintMsg = '', hintT = 0;
const openTabs = () => TABS.filter((t) => !t.when || t.when());
function curTab() { const o = openTabs(); if (tab >= o.length) tab = 0; return o[tab]; }

// --- Input: edges and repeats ---
const BUTTONS = [UP, DOWN, LEFT, RIGHT, A, B, X, Y, L, R, START, SELECT];
const held = new Uint16Array(12);
function readPad() { for (const b of BUTTONS) held[b] = btn(b) ? held[b] + 1 : 0; }
const pressed = (b) => held[b] === 1;
/** A press, then repeats while held: after 18 frames every 6, after a second every 2. */
function rep(b) { const h = held[b]; return h === 1 || (h >= 18 && h < 78 && (h - 18) % 6 === 0) || (h >= 78 && h % 2 === 0); }
const handRep = () => held[B] === 1 || (held[B] > 1 && held[B] % 15 === 1);

// --- State ---
let skipTitle = false; // tests set this to land straight in a new run
let state = 'title', paused = false, timer = 0, clock = 0, sub = 0, saveT = 0;
let titleSel = 0, pauseSel = 0, confirm = false;
let EDGE_RGB = [0, 0, 0];
let bits = []; // cogs dropping in the view: { x, y, vy }

function init() {
  if (dget(VERSION_SLOT) !== SAVE_VERSION) { for (let i = 0; i < 256; i++) dset(i, 0); dset(VERSION_SLOT, SAVE_VERSION); }
  loadFont(); loadBook(); loadSettings(); EDGE_RGB = color(EDGE);
  bg(0, { show: false }); bg(2, { show: false }); // until the views use them (step 6)
  const b = ART.scenes.bench;
  bg(1, { mx: b.mx, my: b.my, mw: b.w, mh: b.h, x: 0, y: -(VIEW_H - b.h * 8), wrap: false, show: true });
  if (skipTitle) newRun(1); else toTitle();
}

function toTitle() { state = 'title'; timer = 0; titleSel = 0; confirm = false; paused = false; play(SONG.title); }
function newRun(seed) {
  G = freshRun(seed); logRows = []; typing = 0; tab = 0; row = 0; top = 0; bits = [];
  state = 'play'; timer = 0; paused = false;
  raise('start'); saveRun(); play(SONG.play);
}
function continueRun() { loadRun(); state = 'play'; timer = 0; paused = false; bits = []; play(SONG.play); }

// --- Update ---
function update() {
  readPad(); clock++;
  if (paused) updatePause();
  else if (state === 'title') updateTitle();
  else if (state === 'play') updatePlay();
  else if (state === 'log') updateLog();
  timer++;
}

function updateTitle() {
  const items = titleItems();
  if (confirm) {
    if (pressed(UP) || pressed(DOWN)) { titleSel ^= 1; fx(SFX.move); }
    if (pressed(B)) { confirm = false; titleSel = 1; fx(SFX.move); }
    else if (pressed(A) || pressed(START)) {
      fx(SFX.select); confirm = false;
      if (titleSel === 1) newRun(rndi(1, 0x7fffffff)); else titleSel = 0;
    }
    return;
  }
  if (pressed(UP)) { titleSel = (titleSel + items.length - 1) % items.length; fx(SFX.move); }
  if (pressed(DOWN)) { titleSel = (titleSel + 1) % items.length; fx(SFX.move); }
  if (pressed(A) || pressed(START)) {
    fx(SFX.select);
    const it = items[titleSel];
    if (it === 'CONTINUE') continueRun();
    else if (hasRun()) { confirm = true; titleSel = 0; }
    else newRun(rndi(1, 0x7fffffff));
  }
}
const titleItems = () => (hasRun() ? ['CONTINUE', 'NEW STORY'] : ['NEW STORY']);

function updatePlay() {
  if (pressed(START)) { paused = true; pauseSel = 0; saveRun(); fx(SFX.pause); return; }
  if (pressed(SELECT)) { state = 'log'; logScroll = 0; fx(SFX.move); return; }
  const t = curTab(), rows = t.rows();
  if (row >= rows.length) row = rows.length - 1;
  const r = rows[row];
  if (rep(UP) && row > 0) { row--; fx(SFX.move); }
  if (rep(DOWN) && row < rows.length - 1) { row++; fx(SFX.move); }
  const o = openTabs().length;
  const tabTo = (d) => { if (o > 1) { tab = (tab + d + o) % o; row = 0; top = 0; fx(SFX.move); } };
  if (pressed(L)) tabTo(-1); if (pressed(R)) tabTo(1);
  if (r.adj) { if (rep(LEFT)) doRow(() => r.adj(-1)); if (rep(RIGHT)) doRow(() => r.adj(1)); }
  else { if (pressed(LEFT)) tabTo(-1); if (pressed(RIGHT)) tabTo(1); }
  if (rep(A) && r.a) doRow(r.a);
  if (handRep()) { if (ACT.hand()) { fx(SFX.clink); dropCog(); } else hint(why); }
  if (row < top) top = row; if (row >= top + ROWS_SHOWN) top = row - ROWS_SHOWN + 1;
  if (++sub >= TICK_FRAMES) { sub = 0; step(TICK); }
  if (++saveT >= SAVE_EVERY) { saveT = 0; saveRun(); }
  if (typing && clock % 1 === 0) typed += 2;
  for (const c of bits) { c.vy += 0.25; c.y += c.vy; }
  bits = bits.filter((c) => c.y < VIEW_H - 22);
}
function doRow(f) {
  if (f()) { fx(SFX.select); if (f === ACT.hand) dropCog(); } else { fx(SFX.no); hint(why); }
}
function hint(s) { hintMsg = s; hintT = 150; }
function dropCog() { if (bits.length < 12) bits.push({ x: 84 + rndi(0, 6), y: 50, vy: -1.5 }); }

function updateLog() {
  const n = logRows.length, page = 17;
  if (rep(UP)) logScroll = Math.min(Math.max(0, n - page), logScroll + 1);
  if (rep(DOWN)) logScroll = Math.max(0, logScroll - 1);
  if (pressed(SELECT) || pressed(B) || pressed(START) || pressed(A)) { state = 'play'; fx(SFX.move); }
}

const PAUSE = () => ['RESUME', 'THE STORY SO FAR', `MUSIC: ${musicOn ? 'ON' : 'OFF'}`, `EFFECTS: ${soundOn ? 'ON' : 'OFF'}`, 'SAVE AND QUIT'];
function updatePause() {
  const n = PAUSE().length;
  if (pressed(UP)) { pauseSel = (pauseSel + n - 1) % n; fx(SFX.move); }
  if (pressed(DOWN)) { pauseSel = (pauseSel + 1) % n; fx(SFX.move); }
  if (pressed(B) || (pressed(START) && pauseSel === 0)) { paused = false; fx(SFX.pause); return; }
  if (!(pressed(A) || pressed(START))) return;
  fx(SFX.select);
  if (pauseSel === 0) paused = false;
  else if (pauseSel === 1) { paused = false; state = 'log'; logScroll = 0; }
  else if (pauseSel === 2) { musicOn ^= 1; saveSettings(); const s = playing; playing = -2; play(musicOn ? (s >= 0 ? s : SONG.play) : -1); }
  else if (pauseSel === 3) { soundOn ^= 1; saveSettings(); }
  else { saveRun(); toTitle(); }
}

// --- Draw ---
function draw() {
  cls();
  if (state === 'title') drawTitle();
  else if (state === 'log') drawFullLog();
  else { drawView(); drawTabs(); drawPanel(); drawLog(); }
  if (paused) drawPause();
}

function drawView() {
  sprite(ART.sprites.pip, 70, VIEW_H - 24 - 16 + (clock % 40 < 20 ? 0 : 1));
  for (let i = 0; i < Math.min(G.tinkers, 12); i++) {
    const x = 120 + i * 10 + Math.round(Math.sin((clock + i * 23) / 20) * 2);
    sprite(ART.sprites.tinker, x, VIEW_H - 24 - 8 + ((clock + i * 7) % 16 < 8 ? 0 : -1));
  }
  for (const c of bits) sprite(ART.sprites.cog, c.x, c.y);
  const pile = Math.min(6, Math.ceil(G.cogs / 20));
  for (let i = 0; i < pile; i++) sprite(ART.sprites.cog, 92 + (i % 3) * 6, VIEW_H - 32 - Math.floor(i / 3) * 4);
}

function drawTabs() {
  rectfill(0, TAB_Y, 256, 12, EDGE);
  line(0, TAB_Y + 11, 255, TAB_Y + 11, LINE);
  const o = openTabs(); let x = 6;
  o.forEach((t, i) => {
    const on = i === tab;
    if (on) { x = tx(LM, x, TAB_Y + 2, GOLD) + 2; x = tx(t.name, x, TAB_Y + 2, GOLD) + 2; x = tx(RM, x, TAB_Y + 2, GOLD) + 8; }
    else x = tx(t.name, x, TAB_Y + 2, DIM) + 10;
  });
}

function drawPanel() {
  rectfill(0, PANEL_Y, 256, LOG_Y - PANEL_Y, PAPER);
  const y0 = PANEL_Y + 3;
  const made = fmt(G.made);
  sys(made, 6, y0, BRASS);
  tx(made === '1' ? 'cog made' : 'cogs made', 6 + made.length * 8 + 4, y0, DIM);
  const coin = money(G.coin);
  sys(coin, 250 - coin.length * 8, y0, GOOD);
  const t = curTab();
  tx(t.info().join('   '), 6, y0 + 12, INK);
  line(4, y0 + 22, 251, y0 + 22, LINE);
  const rows = t.rows();
  for (let k = 0; k < ROWS_SHOWN; k++) {
    const i = top + k, r = rows[i]; if (!r) break;
    const y = y0 + 26 + k * 10, on = i === row, can = r.ok();
    if (on) rectfill(3, y - 1, 250, 10, ROWC);
    if (on) tx('>', 6, y, GOLD);
    tx(r.t, 13, y, can ? INK : DIM);
    txr(r.v(), 250, y, on ? GOLD : can ? BRASS : DIM);
  }
  if (top > 0) tx('^', 244, y0 + 18, DIM);
  if (top + ROWS_SHOWN < rows.length) tx('v', 244, y0 + 26 + ROWS_SHOWN * 10 - 3, DIM);
  const r = rows[row];
  const h = hintT > 0 ? hintMsg : r ? r.h() : '';
  if (hintT > 0) hintT--;
  tx(h, 6, LOG_Y - 11, hintT > 0 ? BAD : DIM);
}

function drawLog() {
  rectfill(0, LOG_Y, 256, 224 - LOG_Y, EDGE);
  line(0, LOG_Y, 255, LOG_Y, LINE);
  const n = logRows.length, from = Math.max(0, n - 3);
  let left = typed;
  const firstTyping = n - typing;
  for (let i = from; i < n; i++) {
    let s = logRows[i].s;
    if (typing && i >= firstTyping) {
      // the newest line types itself in: the rows before it in the same story line are counted first
      let before = 0; for (let j = firstTyping; j < i; j++) before += logRows[j].s.length;
      left = typed - before; if (left <= 0) continue;
      if (left < s.length) s = s.slice(0, left);
    }
    tx(s, 5, LOG_Y + 3 + (i - from) * 10, i >= firstTyping && typing ? INK : LOGC);
  }
  if (typing) { let all = 0; for (let j = firstTyping; j < n; j++) all += logRows[j].s.length; if (typed >= all) typing = 0; }
}

function drawFullLog() {
  rectfill(0, 0, 256, 224, PAPER);
  sysc('THE STORY SO FAR', 6, BRASS);
  line(8, 18, 247, 18, LINE);
  const page = 17, n = logRows.length, end = n - logScroll, from = Math.max(0, end - page);
  for (let i = from; i < end; i++) tx(logRows[i].s, 6, 24 + (i - from) * 10, i === n - 1 ? INK : LOGC);
  tx('UP and DOWN to read back.  B to return.', 6, 214, DIM);
}

function drawTitle() {
  sysc('CLOCKWORK', 40, BRASS); sysc('DOMINION', 52, GOLD);
  sprite(ART.sprites.pip, 120, 66);
  if (confirm) {
    rectfill(40, 104, 176, 56, PAPER); rect(40, 104, 176, 56, LINE);
    txc('Start a new story?', 112, INK); txc('The one you have will be lost.', 122, DIM);
    ['KEEP MY STORY', 'START AGAIN'].forEach((s, i) => sys(`${i === titleSel ? '>' : ' '} ${s}`, 64, 136 + i * 10, i === titleSel ? GOLD : DIM));
    return;
  }
  titleItems().forEach((s, i) => sys(`${i === titleSel ? '> ' : '  '}${s}`, 84, 120 + i * 14, i === titleSel ? GOLD : DIM));
  txc('A to choose', 200, DIM);
}

function drawPause() {
  const items = PAUSE();
  rectfill(56, 60, 144, 26 + items.length * 12, PAPER); rect(56, 60, 144, 26 + items.length * 12, LINE);
  sysc('PAUSED', 68, BRASS);
  items.forEach((s, i) => tx(`${i === pauseSel ? '>' : ' '} ${s}`, 72, 86 + i * 12, i === pauseSel ? GOLD : INK));
}

/** Each line: the wall's lamplight in the view, the panel's ink below it. */
function scanline(y) {
  if (y < VIEW_H) gradientLine(ART.gradients.wall, y);
  else if (y === VIEW_H) color(0, EDGE_RGB[0], EDGE_RGB[1], EDGE_RGB[2]);
}
